import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [first, second] = input;
const [nStr, kStr] = first.split(" ");
const n = Number(nStr);
const a = second.split(" ");

// N 回で元に戻るので K mod N 回だけ回す。K は大きいので BigInt で余りを取る
const k = Number(BigInt(kStr) % BigInt(n));
const rotated = [...a.slice(n - k), ...a.slice(0, n - k)];
console.log(rotated.join(" "));
